code.formula:
@Command([EditDocument];"1");

@If (Comp= ""; @Return(@Do(@Command([EditGotoField];"Comp") ;@Prompt([Ok];"Missing Value"; "Please select Company before proceeding!")));"");
@If (Category= ""; @Return(@Do(@Command([EditGotoField];"Category") ;@Prompt([Ok];"Missing Value"; "Please select Category before proceeding!")));"");
@If (Section= ""; @Return(@Do(@Command([EditGotoField];"Section") ;@Prompt([Ok];"Missing Value"; "Please select Section before proceeding!")));"");
@If (Dept= ""; @Return(@Do(@Command([EditGotoField];"Dept") ;@Prompt([Ok];"Missing Value"; "Please select Department before proceeding!")));"");
@If (HOS= ""; @Return(@Do(@Command([EditGotoField];"HOS") ;@Prompt([Ok];"Missing Value"; "Please select Section Head before proceeding!")));"");
@If (HOD= ""; @Return(@Do(@Command([EditGotoField];"HOD") ;@Prompt([Ok];"Missing Value"; "Please select Department Head before proceeding!")));"");
@If (Month= ""; @Return(@Do(@Command([EditGotoField];"Month") ;@Prompt([Ok];"Missing Value"; "Please select Month before proceeding!")));"");
@If (Year= ""; @Return(@Do(@Command([EditGotoField];"Year") ;@Prompt([Ok];"Missing Value"; "Please select Year before proceeding!")));"");

@If(@AttachmentNames="";@Return(@Do(@Command([EditGotoField];"Attch") ;@Prompt([Ok];"Missing Value"; "The Attachment is empty!")));"");

FIELD SubmittedBy 		:= @V3UserName;
FIELD SubmittedDate 	:=@Today;
FIELD CA 					:="Submitted";

@Command([FileSave]);

@MailSend(HOS;DocAuthor:CC;NULL;@DbTitle + " - Submitted for Approval.";NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);
@If(Changes="Yes";@MailSend(HR;NULL;NULL;@DbTitle + " - Submitted for Approval - "+Changes;NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);NULL);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

