code.formula:
@If(Month="December";12;
Month="November";11;
Month="October";10;
Month="September";9;
Month="August";8;
Month="July";7;
Month="June";6;
Month="May";5;
Month="April";4;
Month="March";3;
Month="February";2;
Month="January";1;
"")

@Command([EditDocument];"1");

@If (Comp= ""; @Return(@Do(@Command([EditGotoField];"Comp") ;@Prompt([Ok];"Missing Value"; "Please select Company before proceeding!")));"");
