@If(@AttachmentNames="";@Return(@Do(@Command([EditGotoField];"Attch") ;@Prompt([Ok];"Missing Value"; "The Attachment is empty!")));"");

FIELD SubmittedBy 		:= @V3UserName;
FIELD SubmittedDate 	:=@Today;
FIELD CA 					:="Submitted";

@Command([FileSave]);

@MailSend(HOS;DocAuthor:CC;NULL;@DbTitle + " - Submitted for Approval.";NULL;"Please follow this doclink   -----> " ;[IncludeDoclink]);
